import fitz, numpy as np
d=fitz.open('eprint/Fig2.pdf')
p=d[0]
draws=p.get_drawings()

def path_points(dr):
    pts=[]
    for it in dr['items']:
        if it[0]=='l':
            if not pts: pts.append((it[1].x,it[1].y))
            pts.append((it[2].x,it[2].y))
        elif it[0]=='c':
            if not pts: pts.append((it[1].x,it[1].y))
            for q in (it[2],it[3],it[4]): pts.append((q.x,q.y))
    return np.array(pts)

x0,x1=92.341552734375,985.1415405273438
y0,y1=450.3822021484375,15.502197265625
def tom(x): return 10**((x-x0)/(x1-x0)*3.0)      # MeV
def tog(y): return 10**(-11 + (y-y0)/(y1-y0)*7.0)

for idx,name in [(192,'0.1B'),(193,'1B')]:
    pts=path_points(draws[idx])
    m=tom(pts[:,0]); g=tog(pts[:,1])
    print(name, len(pts), 'first',m[0],g[0],'last',m[-1],g[-1])
    print(' mass range %.3g-%.3g, g range %.3g-%.3g'%(m.min(),m.max(),g.min(),g.max()))
    np.save(name+'.npy', np.column_stack([m,g]))
    # print a decimated trace to see ordering
    for i in range(0,len(pts),max(1,len(pts)//25)):
        print('  %3d m=%.4g g=%.4g'%(i,m[i],g[i]))
